import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import 'package:http/http.dart' as http;
import 'package:shared_preferences/shared_preferences.dart';
import 'dart:convert'; import 'package:socket_io_client/socket_io_client.dart' as IO;
class Api{String base='http://10.0.2.2:5000';String? token;Future<void>load()async=>token=(await SharedPreferences.getInstance()).getString('token');Future<Map<String,dynamic>>call(String method,String path,[Map<String,dynamic>? body])async{final h={'Content-Type':'application/json',if(token!=null)'Authorization':'Bearer $token'};final u=Uri.parse(base+path);final r=switch(method){'POST'=>await http.post(u,headers:h,body:jsonEncode(body??{})),'PATCH'=>await http.patch(u,headers:h,body:jsonEncode(body??{})),_=>await http.get(u,headers:h)};final d=r.body.isEmpty?<String,dynamic>{}:jsonDecode(r.body);if(r.statusCode>=400)throw Exception(d['error']??'Request failed');return Map<String,dynamic>.from(d);}}
class App extends ChangeNotifier{final api=Api();bool ready=false;App(){init();}Future<void>init()async{await api.load();ready=true;notifyListeners();}Future<String?>auth(bool reg,String name,String email,String pass)async{try{final d=await api.call('POST',reg?'/api/auth/register':'/api/auth/login',{'name':name,'email':email,'password':pass});api.token=d['token'];await (await SharedPreferences.getInstance()).setString('token',api.token!);notifyListeners();return null;}catch(e){return e.toString().replaceFirst('Exception: ','');}}Future<void>logout()async{api.token=null;await (await SharedPreferences.getInstance()).remove('token');notifyListeners();}}
void main()=>runApp(ChangeNotifierProvider(create:(_)=>App(),child:const Chatify()));
class Chatify extends StatelessWidget{const Chatify({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Chatify',theme:ThemeData(useMaterial3:true,colorSchemeSeed:const Color(0xFF5B4BFF)),home:Consumer<App>(builder:(_,a,__){if(!a.ready)return const Scaffold(body:Center(child:CircularProgressIndicator()));return a.api.token==null?const Auth():const Home();}));}
class Auth extends StatefulWidget{const Auth({super.key});@override State<Auth>createState()=>_Auth();}
class _Auth extends State<Auth>{bool reg=false,busy=false;final n=TextEditingController(),e=TextEditingController(),p=TextEditingController();Future<void>go()async{setState(()=>busy=true);final err=await context.read<App>().auth(reg,n.text,e.text,p.text);if(mounted){setState(()=>busy=false);if(err!=null)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(err)));}}@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(28),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.forum_rounded,size:64),const SizedBox(height:12),const Text('Chatify',style:TextStyle(fontSize:38,fontWeight:FontWeight.bold)),const Text('Chat. Remember. Let Go.'),const SizedBox(height:32),if(reg)TextField(controller:n,decoration:const InputDecoration(labelText:'Name',prefixIcon:Icon(Icons.person_outline))),if(reg)const SizedBox(height:12),TextField(controller:e,decoration:const InputDecoration(labelText:'Email',prefixIcon:Icon(Icons.email_outlined))),const SizedBox(height:12),TextField(controller:p,obscureText:true,decoration:const InputDecoration(labelText:'Password',prefixIcon:Icon(Icons.lock_outline))),const SizedBox(height:20),FilledButton(onPressed:busy?null:go,child:Text(busy?'Working…':reg?'Create account':'Login')),TextButton(onPressed:()=>setState(()=>reg=!reg),child:Text(reg?'Already registered? Login':'Create an account'))])))));}}
class Home extends StatefulWidget{const Home({super.key});@override State<Home>createState()=>_Home();}
class _Home extends State<Home>{int tab=0;List<dynamic>users=[],convos=[],memories=[];@override void initState(){super.initState();loadConvos();}Future<void>loadConvos()async{try{final d=await context.read<App>().api.call('GET','/api/conversations');setState(()=>convos=d['conversations']);}catch(_){}}Future<void>search(String q)async{if(q.length<2)return;try{final d=await context.read<App>().api.call('GET','/api/users/search?q=${Uri.encodeQueryComponent(q)}');setState(()=>users=d['users']);}catch(_){}}Future<void>_newGroup()async{if(users.isEmpty){await search('a');}if(!mounted||users.isEmpty)return;final title=TextEditingController();await showDialog(context:context,builder:(d)=>AlertDialog(title:const Text('Create group'),content:TextField(controller:title,decoration:const InputDecoration(labelText:'Group name')),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Cancel')),FilledButton(onPressed:()async{if(title.text.trim().isEmpty)return;await context.read<App>().api.call('POST','/api/conversations/group',{'title':title.text.trim(),'memberIds':[users.first['_id']]});if(d.mounted)Navigator.pop(d);},child:const Text('Create'))]));loadConvos();}Future<void>loadMemories()async{try{final d=await context.read<App>().api.call('GET','/api/memories');setState(()=>memories=d['memories']);}catch(_){}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(['Chats','Memories','Contacts','Profile'][tab]),actions:tab==2?[IconButton(onPressed:_newGroup,icon:const Icon(Icons.group_add_outlined))]:null),body:tab==0?_chatList():tab==1?_memoryList():tab==2?_contacts():_profile(),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i){setState(()=>tab=i);if(i==1)loadMemories();},destinations:const[NavigationDestination(icon:Icon(Icons.chat_bubble_outline),label:'Chats'),NavigationDestination(icon:Icon(Icons.auto_awesome_outlined),label:'Memories'),NavigationDestination(icon:Icon(Icons.people_outline),label:'Contacts'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Profile')]));Widget _chatList()=>convos.isEmpty?const Center(child:Text('No conversations yet. Open Contacts to start one.')):ListView(children:convos.map((x){final ps=(x['participants'] as List);final other=ps.first;return ListTile(leading:CircleAvatar(child:Text((other['name']??'?')[0])),title:Text(other['name']??x['title']??'Group'),subtitle:Text(x['lastMessage']?['text']??'Start the conversation'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>Chat(c:x))));}).toList());Widget _contacts()=>Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(onChanged:search,decoration:const InputDecoration(labelText:'Find people',prefixIcon:Icon(Icons.search)))),Expanded(child:ListView(children:users.map((u)=>ListTile(leading:CircleAvatar(child:Text(u['name'][0])),title:Text(u['name']),subtitle:Text(u['email']),onTap:()async{final d=await context.read<App>().api.call('POST','/api/conversations/direct',{'userId':u['_id']});if(mounted)Navigator.push(context,MaterialPageRoute(builder:(_)=>Chat(c:d['conversation'])));})).toList()))]);Widget _memoryList()=>memories.isEmpty?const Center(child:Text('No memories yet. Save useful information from a conversation.')):ListView(children:memories.map((m)=>Card(child:ListTile(leading:Text({'EVENT':'📅','PAYMENT':'💰','PLACE':'📍','TASK':'✅','NOTE':'📝'}[m['type']]??'💡',style:const TextStyle(fontSize:24)),title:Text(m['title']),subtitle:Text(m['description']??''))).toList());Widget _profile()=>Center(child:FilledButton.icon(onPressed:()=>context.read<App>().logout(),icon:const Icon(Icons.logout),label:const Text('Logout')));}
class Chat extends StatefulWidget{final dynamic c;const Chat({super.key,required this.c});@override State<Chat>createState()=>_Chat();}
class _Chat extends State<Chat>{List<dynamic>ms=[];final input=TextEditingController();String expiry='NONE';IO.Socket? socket;@override void initState(){super.initState();load();final app=context.read<App>();socket=IO.io(app.api.base,IO.OptionBuilder().setTransports(['websocket']).setAuth({'token':app.api.token}).disableAutoConnect().build());socket!.connect();socket!.onConnect((_){socket!.emit('conversation:join',widget.c['_id']);});socket!.on('message:new',(m){if(m is Map&&mounted)setState(()=>ms.add(m));});}Future<void>load()async{try{final d=await context.read<App>().api.call('GET','/api/conversations/${widget.c['_id']}/messages');setState(()=>ms=d['messages']);}catch(_){}}Future<void>send()async{if(input.text.trim().isEmpty)return;final d=await context.read<App>().api.call('POST','/api/conversations/${widget.c['_id']}/messages',{'text':input.text.trim(),'expiryType':expiry,'expiresInSeconds':expiry=='AFTER_TIME'?3600:null});setState(()=>ms.add(d['message']));input.clear();}@override void dispose(){socket?.disconnect();socket?.dispose();input.dispose();super.dispose();}Future<void>saveMemory()async{if(ms.isEmpty)return;final last=ms.last;final x=await context.read<App>().api.call('POST','/api/memories/extract',{'text':last['text']});final cs=x['candidates'] as List;if(cs.isEmpty)return;final chosen=Map<String,dynamic>.from(cs.first as Map); await context.read<App>().api.call('POST','/api/memories',{...chosen,'conversationId':widget.c['_id'],'sourceMessageId':last['_id']});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Memory saved')));}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.c['title']??'Chat'),actions:[IconButton(onPressed:saveMemory,icon:const Icon(Icons.auto_awesome))]),body:Column(children:[Expanded(child:ListView(children:ms.map((m)=>Align(alignment:Alignment.centerRight,child:Container(margin:const EdgeInsets.all(7),padding:const EdgeInsets.all(12),constraints:const BoxConstraints(maxWidth:320),decoration:BoxDecoration(color:Theme.of(context).colorScheme.primaryContainer,borderRadius:BorderRadius.circular(18)),child:Text(m['expiredAt']!=null?'Expired message':m['text']??''))).toList())),SafeArea(child:Row(children:[PopupMenuButton<String>(onSelected:(v)=>setState(()=>expiry=v),itemBuilder:(_)=>const[PopupMenuItem(value:'NONE',child:Text('Keep permanently')),PopupMenuItem(value:'AFTER_READ',child:Text('Delete after reading')),PopupMenuItem(value:'AFTER_TIME',child:Text('Delete after 1 hour')),PopupMenuItem(value:'AFTER_REPLY',child:Text('Delete after reply'))],icon:const Icon(Icons.timer_outlined)),Expanded(child:TextField(controller:input,maxLines:4,decoration:const InputDecoration(hintText:'Message',border:InputBorder.none,contentPadding:EdgeInsets.all(14))),),IconButton(onPressed:send,icon:const Icon(Icons.send))]))]));}
